#!/usr/bin/env bash
# ============================================================================
# FIRONOVA — Installeur SEO complet (idempotent)
# Ajoute: sitemap dynamique, endpoint SEO produit (public),
#         + pilotage SEO admin (réglages globaux, santé, édition par produit),
#         + champs SEO sur le modèle produit, + SEO global exposé via /meta.
# À exécuter depuis /app :  bash install_seo_backend.sh
# ============================================================================
set -euo pipefail
cd "$(dirname "$0")"
SERVER="backend/server.py"; [ -f "$SERVER" ] || SERVER="server.py"
[ -f "$SERVER" ] || { echo "server.py introuvable"; exit 1; }
cp "$SERVER" "${SERVER}.bak-seo-$(date +%Y%m%d-%H%M%S)"
echo "Backup créé."
export SEO_PUB_B64=''
export SEO_ADM_B64=''

python3 - "$SERVER" << 'PYEOF2'
import sys, re, ast, base64, os
path = sys.argv[1]
src = open(path).read()

# 1) Champs SEO produit (idempotent)
if "meta_title_en" not in src:
    anchor = '    synonyms: List[str] = []           # ex. ["Sermorelin", "GRF 1-29"]\n    variants: List[ProductVariant] = []'
    inject = ('    synonyms: List[str] = []           # ex. ["Sermorelin", "GRF 1-29"]\n'
              '    meta_title_en: str = ""\n    meta_title_fr: str = ""\n'
              '    meta_description_en: str = ""\n    meta_description_fr: str = ""\n'
              '    og_image_url: str = ""\n    variants: List[ProductVariant] = []')
    if anchor in src:
        src = src.replace(anchor, inject, 1); print("  champs SEO produit ajoutes")
    else:
        print("  ! ancre champs produit introuvable")
else:
    print("  champs SEO produit deja presents")

# 2) Bloc public
pub = base64.b64decode(os.environ["SEO_PUB_B64"]).decode()
w1 = "\n\n# ===== FIRONOVA_SEO_BLOCK_START =====\n" + pub + "\n# ===== FIRONOVA_SEO_BLOCK_END =====\n"
if "FIRONOVA_SEO_BLOCK_START" in src:
    src = re.sub(r"# ===== FIRONOVA_SEO_BLOCK_START =====.*?# ===== FIRONOVA_SEO_BLOCK_END =====\n", w1.strip()+"\n", src, flags=re.DOTALL); print("  bloc SEO public remplace")
else:
    src = src.replace("app.include_router(api)", w1 + "\napp.include_router(api)", 1); print("  bloc SEO public injecte")

# 3) Bloc admin
adm = base64.b64decode(os.environ["SEO_ADM_B64"]).decode()
w2 = "\n\n# ===== FIRONOVA_SEO_ADMIN_BLOCK_START =====\n" + adm + "\n# ===== FIRONOVA_SEO_ADMIN_BLOCK_END =====\n"
if "FIRONOVA_SEO_ADMIN_BLOCK_START" in src:
    src = re.sub(r"# ===== FIRONOVA_SEO_ADMIN_BLOCK_START =====.*?# ===== FIRONOVA_SEO_ADMIN_BLOCK_END =====\n", w2.strip()+"\n", src, flags=re.DOTALL); print("  bloc SEO admin remplace")
else:
    src = src.replace("app.include_router(api)", w2 + "\napp.include_router(api)", 1); print("  bloc SEO admin injecte")

# 4) /meta expose le SEO global (idempotent)
if '"seo": await _seo_get_settings()' not in src:
    a = '        "launch_coupon_code": LAUNCH_COUPON_CODE,\n        # PRELAUNCH_PREVIEW_TOKEN'
    b = '        "launch_coupon_code": LAUNCH_COUPON_CODE,\n        "seo": await _seo_get_settings(),\n        # PRELAUNCH_PREVIEW_TOKEN'
    if a in src:
        src = src.replace(a, b, 1); print("  /meta expose le SEO global")
    else:
        print("  ! ancre /meta introuvable")
else:
    print("  /meta deja OK")

ast.parse(src); open(path,"w").write(src)
print("OK - server.py a jour, AST valide.")
PYEOF2
echo "Termine. Redemarre le backend."
